let state='menu',distance=0,hp=3,shards=0,lane=0,x=0,vy=0,jumpY=0,attack=0,cooldown=0,invul=0,nextChunk=0,time=0,biomeIndex=-1,pending=new Set(),particles=[],chunks=[],objects=[],found=0;const LENGTH=32,SPAN=420;const rand=(a,b)=>a+Math.random()*(b-a);const hero=new T.Group();scene.add(hero);const body=new T.Group();hero.add(body);mesh('cone','#c37535',0,1.4,0,.85,1.7,.65,body);mesh('ball','#e2b78a',0,2.65,0,.36,.43,.36,body);mesh('ball','#43332c',0,2.9,.03,.37,.22,.36,body);mesh('box','#e6be6d',0,1.9,-.33,.15,1.1,.1,body);const limbs=[];for(const side of [-1,1]){const leg=new T.Group();leg.position.set(side*.23,.9,0);body.add(leg);mesh('box','#423c3b',0,-.42,0,.26,.85,.28,leg);mesh('box','#403833',0,-.82,-.1,.3,.18,.5,leg);limbs.push(leg);const arm=new T.Group();arm.position.set(side*.51,2.05,0);body.add(arm);mesh('box','#be743c',0,-.4,0,.25,.8,.27,arm);mesh('ball','#ddb38b',0,-.86,0,.16,.18,.16,arm);limbs.push(arm)}const staff=new T.Group();limbs[3].add(staff);mesh('cyl','#503c2c',0,-.5,-.3,.055,2.7,.055,staff);mesh('ball','#ffe6a0',0,.9,-.3,.16,.16,.16,staff);
