function spawn(kind,xx,zz,b,chunk){const g=new T.Group();g.position.set(xx,0,zz);chunk.add(g);let radius=.9,rig=null;if(kind==='tree'){mesh('cyl','#75604a',0,1.6,0,.23,3.2,.23,g);for(let i=0;i<3;i++)mesh('cone',b.tree,0,2.5+i*.85,0,1.7-i*.35,2,1.7-i*.35,g);radius=1.25}else if(kind==='bush'){for(let i=0;i<3;i++)mesh('ball',b.tree,(i-1)*.45,.5,0,.65,.7,.65,g)}else if(kind==='fossil'){mesh('ball','#b99973',0,.7,0,1.1,.8,.8,g);const ring=new T.Mesh(new T.TorusGeometry(.43,.08,6,16),mat('#ffe4ac'));ring.position.set(0,.8,-.66);g.add(ring);mesh('ball','#ffe4ac',0,.8,-.68,.12,.12,.1,g)}else if(kind==='creature'){rig=buildCreature(Math.floor((-zz)/SPAN)%5,g,mesh)}else if(kind==='cave'){mesh('ball',b.rock,-1,1,0,1,1.7,1.2,g);mesh('ball',b.rock,1,1,0,1,1.7,1.2,g);mesh('box',b.rock,0,2.3,0,3,1,2,g);radius=1.8}else{mesh('ball',b.rock,0,.7,0,rand(.6,1.2),rand(.6,1.4),.85,g)}objects.push({g,rig,kind,z:zz,x:xx,radius,done:false,type:Math.floor((-zz)/SPAN)%5});}
function chunk(n){let z=-n*LENGTH,bi=Math.floor(n*LENGTH/SPAN)%5,b=biomes[bi];const g=new T.Group();scene.add(g);chunks.push({g,z});mesh('box',b.ground,0,-.5,z-16,90,1,32,g);mesh('box',bi===3?'#d5bf8e':'#d7b98b',0,.015,z-16,9,.08,32,g);if(bi===3)for(let s of [-1,1])mesh('box','#559fa9',s*22,-.1,z-16,27,.15,32,g);for(let i=0;i<6;i++){let s=i%2?1:-1;mesh('cone',b.rock,s*rand(24,65),rand(2,8),z-rand(0,32),rand(8,19),rand(20,55),rand(8,15),g)}for(let i=0;i<12;i++){const zz=z-rand(0,32),xx=rand(-19,19);if(Math.abs(xx)<5&&n<2)continue;spawn(Math.random()<.4?'tree':Math.random()<.5?'bush':'rock',xx,zz,b,g)}if(n>0){spawn(n%3===0?'fossil':n%5===0?'cave':'rock',[-3,0,3][n%3],z-16,b,g);if(n%4===2)spawn('creature',[-5,5][n%2],z-8,b,g)}}
function toast(t){$('#toast').textContent=t;$('#toast').style.opacity=1;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.opacity=0,3000)}function burst(o){o.done=true;o.g.visible=false;shards+=o.kind==='fossil'?12:2;for(let i=0;i<12;i++){const m=mesh('ball',o.kind==='fossil'?'#f6d692':biomes[o.type].rock,o.x,1,o.z,.15,.15,.15);particles.push({m,v:new T.Vector3(rand(-5,5),rand(3,8),rand(-5,5)),life:1.2})}if(o.kind==='fossil'){const id=o.type;if(!save.fossils.includes(id)){save.fossils.push(id);persist();toast('✦ Fosszília feltárva · ősi emlék a könyvben')}hp=Math.min(3,hp+1)}}
function hit(){if(state!=='run'||cooldown>0)return;attack=.45;cooldown=.55;for(const o of objects)if(!o.done&&o.kind!=='creature'&&Math.abs(o.x-x)<3.5&&o.z<hero.position.z+2&&o.z>hero.position.z-9)burst(o)}function move(d){if(state==='run')lane=T.MathUtils.clamp(lane+d,-2,2)}function jump(){if(state==='run'&&jumpY<=.01)vy=9}function book(){const was=state;if(state==='run')state='pause';$('#modal').hidden=false;$('#modal').innerHTML='<small>AZ UTAZÁS NYOMAI</small><h2>A felfedezések könyve</h2><p>Rekord: '+save.best+' m · '+save.runs+' utazás · '+save.shards+' szilánk</p>'+species.map((s,i)=>'<div class="entry">'+(save.creatures.includes(i)?s:'Ismeretlen lény')+'<span>'+(save.creatures.includes(i)?'Feloldva':pending.has(i)?'Következő körben':'?')+'</span></div>').join('')+'<p>Feltárt fosszíliák: '+save.fossils.length+' / 5</p><button id="close">Vissza</button>';$('#close').onclick=()=>{$('#modal').hidden=true;if(was==='run')state='run'}}
function start(){for(const c of chunks)scene.remove(c.g);for(const p of particles)scene.remove(p.m);particles=[];chunks=[];objects=[];distance=0;hp=3;shards=0;lane=x=jumpY=vy=0;nextChunk=0;biomeIndex=-1;pending=new Set();found=0;hero.visible=true;state='run';$('#menu').hidden=true;$('#modal').hidden=true;save.runs++;persist();toast('A jóslat nyomában · J: rombolás, Space: ugrás')}
